import Organization from '../models/Organization.js';
import OrganizationMember from '../models/OrganizationMember.js';

// --------------------------------------------------------------
// Helper
//
// Organization slugs are normally generated by the Organization
// model. If the generated slug collides with an existing
// organization, this helper creates a small random suffix.
// --------------------------------------------------------------
const withRandomSuffix = (slug) =>
  `${slug}-${Math.random().toString(36).slice(2, 6)}`;

// --------------------------------------------------------------
// POST /api/organizations
//
// Creates an organization and, in the same operation, makes the
// requesting user its "owner" via an OrganizationMember record.
//
// A user can have only ONE active organization membership.
// Therefore, before creating an organization, we verify that the
// user does not already belong to an active organization.
//
// This endpoint deliberately does NOT use a Mongo transaction:
// SETU's default local/dev MongoDB runs as a standalone instance
// (no replica set), and transactions require one.
//
// Instead we use a compensating action — if the membership write
// fails after the organization was created, we delete the
// organization we just created.
// --------------------------------------------------------------
const createOrganization = async (req, res, next) => {
  let createdOrganization;

  try {
    const { name, description } = req.body;

    // A user can belong to only one active organization.
    const existingMembership = await OrganizationMember.exists({
      user: req.user.id,
      status: 'active',
    });

    if (existingMembership) {
      return res.status(409).json({
        success: false,
        message:
          'You already belong to an active organization',
      });
    }

    // 1. Validate required fields
    if (!name || !name.trim()) {
      return res.status(400).json({
        success: false,
        message: 'Organization name is required',
      });
    }

    // 2. Create the organization
    //
    // Slug is auto-derived from the name by the model's
    // pre('validate') hook.
    try {
      createdOrganization = await Organization.create({
        name: name.trim(),
        description: description
          ? description.trim()
          : '',
        owner: req.user.id,
      });
    } catch (error) {
      // Duplicate slug — retry once with a randomized suffix.
      if (
        error.code === 11000 &&
        error.keyPattern?.slug
      ) {
        const retrySlug = withRandomSuffix(
          name
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, '-'),
        );

        createdOrganization =
          await Organization.create({
            name: name.trim(),
            description: description
              ? description.trim()
              : '',
            owner: req.user.id,
            slug: retrySlug,
          });
      } else {
        throw error;
      }
    }

    // 3. Make the creator the owner member
    let ownerMembership;

    try {
      ownerMembership =
        await OrganizationMember.create({
          organization: createdOrganization._id,
          user: req.user.id,
          role: 'owner',
          status: 'active',
        });
    } catch (membershipError) {
      // Compensating rollback.
      await Organization.findByIdAndDelete(
        createdOrganization._id,
      );

      throw membershipError;
    }

    // 4. Return organization + membership
    return res.status(201).json({
      success: true,
      data: {
        organization: createdOrganization,
        membership: ownerMembership,
      },
    });
  } catch (error) {
    // Handle Mongoose validation errors
    if (error.name === 'ValidationError') {
      const message = Object.values(error.errors)
        .map((e) => e.message)
        .join(', ');

      return res.status(400).json({
        success: false,
        message,
      });
    }

    next(error);
  }
};

// --------------------------------------------------------------
// GET /api/organizations
//
// Lists every ACTIVE organization the authenticated user belongs
// to, along with the role they hold in each.
// --------------------------------------------------------------
const listMyOrganizations = async (
  req,
  res,
  next,
) => {
  try {
    const memberships =
      await OrganizationMember.find({
        user: req.user.id,
        status: 'active',
      }).populate('organization');

    const organizations = memberships
      .filter(
        (membership) => membership.organization,
      )
      .map((membership) => ({
        organization: membership.organization,
        role: membership.role,
      }));

    return res.status(200).json({
      success: true,
      data: {
        organizations,
      },
    });
  } catch (error) {
    next(error);
  }
};

// --------------------------------------------------------------
// GET /api/organizations/:id
//
// Sits behind loadMembership, so the caller has already been
// confirmed as an active member.
// --------------------------------------------------------------
const getOrganization = async (
  req,
  res,
  next,
) => {
  try {
    return res.status(200).json({
      success: true,
      data: {
        organization: req.organization,
        membership: req.membership,
      },
    });
  } catch (error) {
    next(error);
  }
};

// --------------------------------------------------------------
// PATCH /api/organizations/:id
//
// Sits behind loadMembership +
// requirePermission('organization:manage').
//
// Only name and description are editable here.
// --------------------------------------------------------------
const updateOrganization = async (
  req,
  res,
  next,
) => {
  try {
    const {
      name,
      description,
    } = req.body;

    const updates = {};

    if (name !== undefined) {
      if (!name.trim()) {
        return res.status(400).json({
          success: false,
          message:
            'Organization name cannot be empty',
        });
      }

      updates.name = name.trim();
    }

    if (description !== undefined) {
      updates.description =
        description.trim();
    }

    if (Object.keys(updates).length === 0) {
      return res.status(400).json({
        success: false,
        message:
          'No valid fields provided to update',
      });
    }

    const updatedOrganization =
      await Organization.findByIdAndUpdate(
        req.organization._id,
        updates,
        {
          returnDocument: 'after',
          runValidators: true,
        },
      );

    return res.status(200).json({
      success: true,
      data: {
        organization: updatedOrganization,
      },
    });
  } catch (error) {
    if (error.name === 'ValidationError') {
      const message = Object.values(error.errors)
        .map((e) => e.message)
        .join(', ');

      return res.status(400).json({
        success: false,
        message,
      });
    }

    next(error);
  }
};

// --------------------------------------------------------------
// GET /api/organizations/search
//
// Used by users who do not currently belong to an active
// organization and want to discover an organization to join.
// --------------------------------------------------------------
const discoverOrganizations = async (
  req,
  res,
  next,
) => {
  try {
    const search = String(
      req.query.search || '',
    ).trim();

    const query = search
      ? {
          $or: [
            {
              name: new RegExp(
                search,
                'i',
              ),
            },
            {
              description: new RegExp(
                search,
                'i',
              ),
            },
          ],
        }
      : {};

    const organizations =
      await Organization.find(query)
        .select(
          'name description slug',
        )
        .sort({ name: 1 })
        .limit(30);

    return res.json({
      success: true,
      data: {
        organizations,
      },
    });
  } catch (error) {
    next(error);
  }
};

// --------------------------------------------------------------
// Named exports
// --------------------------------------------------------------
export {
  createOrganization,
  listMyOrganizations,
  getOrganization,
  updateOrganization,
  discoverOrganizations,
};